src/collision/CollisionSystem.ts:
// ============================================================
//  CollisionSystem — Colisão jogador × mapa (CPU)
// ------------------------------------------------------------
//  Colisão é lógica de jogo → roda na CPU (como o documento pede).
//
//  Modelo:
//    - Jogador: um CÍRCULO de raio `radius` no plano XZ, com uma
//      faixa vertical [feet, head] (para saber a que altura ele
//      colide). Isso naturalmente ignora o CHÃO (cuja face de topo
//      fica no nível dos pés) e considera só paredes/obstáculos.
//    - Mapa: cada Box é uma AABB (caixa alinhada aos eixos).
//
//  Resolução POR EIXO (axis-separated):
//    1) aplica o movimento em X e empurra o jogador para fora de
//       qualquer parede sobreposta (na borda X);
//    2) faz o mesmo em Z.
//    Isso é simples, estável e permite "deslizar" ao longo das
//    paredes em vez de travar.
//
//  Técnica: expandimos a AABB pelo raio do jogador e o tratamos
//  como um ponto. Os cantos ficam "quadrados" (colisão levemente
//  antecipada nos cantos), o que é aceitável e comum em FPS.
// ============================================================

import { Box } from "../levels/types";

interface AABB {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
  minZ: number;
  maxZ: number;
}

export class CollisionSystem {
  private readonly aabbs: AABB[];

  constructor(boxes: Box[]) {
    // Pré-calcula os limites (min/max) de cada caixa uma única vez.
    this.aabbs = boxes.map((b) => ({
      minX: b.center[0] - b.size[0] / 2,
      maxX: b.center[0] + b.size[0] / 2,
      minY: b.center[1] - b.size[1] / 2,
      maxY: b.center[1] + b.size[1] / 2,
      minZ: b.center[2] - b.size[2] / 2,
      maxZ: b.center[2] + b.size[2] / 2,
    }));
  }

  // A caixa intersecta a faixa vertical [feet, head] da entidade?
  private verticalOverlap(feet: number, head: number, box: AABB): boolean {
    return feet < box.maxY && head > box.minY;
  }

  // Move `position` por (dx, dz) resolvendo colisões contra o mapa.
  // Muta `position` no lugar.
  //   radius     — raio da entidade (círculo em XZ)
  //   feet, head — faixa vertical ocupada (para saber o que colide;
  //                escolhida acima do chão para não colidir com o piso)
  moveAndCollide(
    position: [number, number, number],
    dx: number,
    dz: number,
    radius: number,
    feet: number,
    head: number,
  ): void {
    // ---- Eixo X ----
    position[0] += dx;
    for (const box of this.aabbs) {
      if (!this.verticalOverlap(feet, head, box)) continue;
      const insideX = position[0] > box.minX - radius && position[0] < box.maxX + radius;
      const insideZ = position[2] > box.minZ - radius && position[2] < box.maxZ + radius;
      if (insideX && insideZ) {
        if (dx > 0) position[0] = box.minX - radius; // vindo da esquerda
        else if (dx < 0) position[0] = box.maxX + radius; // vindo da direita
      }
    }

    // ---- Eixo Z ----
    position[2] += dz;
    for (const box of this.aabbs) {
      if (!this.verticalOverlap(feet, head, box)) continue;
      const insideX = position[0] > box.minX - radius && position[0] < box.maxX + radius;
      const insideZ = position[2] > box.minZ - radius && position[2] < box.maxZ + radius;
      if (insideX && insideZ) {
        if (dz > 0) position[2] = box.minZ - radius; // vindo do sul
        else if (dz < 0) position[2] = box.maxZ + radius; // vindo do norte
      }
    }
  }
}

src/core/InputManager.ts:
// ============================================================
//  InputManager — Entrada de teclado e mouse (CPU)
// ------------------------------------------------------------
//  Centraliza o estado de input. É lógica de jogo pura (CPU),
//  sem nada de GPU.
//
//  Teclado: mantém um conjunto de teclas pressionadas (por "code",
//  independente do layout — KeyW funciona em qualquer teclado).
//
//  Mouse: usa a Pointer Lock API. Quando o ponteiro está "travado"
//  no canvas, o navegador fornece movimentos relativos
//  (movementX/movementY) — ideal para câmera FPS. Acumulamos esse
//  delta e o consumimos uma vez por frame.
// ============================================================

export class InputManager {
  private readonly canvas: HTMLCanvasElement;
  private readonly keys = new Set<string>();

  // Delta de mouse acumulado desde o último consumo (em pixels).
  private mouseDX = 0;
  private mouseDY = 0;

  private pointerLocked = false;

  // Disparo pendente (edge-triggered): vira true no clique e é
  // consumido uma vez por frame. Também guardamos se o botão está
  // segurado, para armas automáticas na FASE 10.
  private fireQueued = false;
  private fireHeld = false;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;

    // ---- Teclado ----
    window.addEventListener("keydown", (e) => {
      this.keys.add(e.code);
      // Evita a página rolar com as setas/espaço durante o jogo.
      if (this.pointerLocked) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => {
      this.keys.delete(e.code);
    });

    // ---- Pointer Lock: clicar no canvas trava o mouse ----
    this.canvas.addEventListener("click", () => {
      if (!this.pointerLocked) void this.canvas.requestPointerLock();
    });

    document.addEventListener("pointerlockchange", () => {
      this.pointerLocked = document.pointerLockElement === this.canvas;
      // Ao sair do lock, zera as teclas para o jogador não "andar sozinho".
      if (!this.pointerLocked) {
        this.keys.clear();
        this.fireHeld = false;
      }
    });

    // ---- Movimento do mouse (só conta quando travado) ----
    window.addEventListener("mousemove", (e) => {
      if (!this.pointerLocked) return;
      this.mouseDX += e.movementX;
      this.mouseDY += e.movementY;
    });

    // ---- Disparo (botão esquerdo, só quando travado) ----
    // Obs.: o PRIMEIRO clique apenas engata o pointer lock (ainda não
    // travado aqui), então ele não dispara — comportamento desejado.
    window.addEventListener("mousedown", (e) => {
      if (!this.pointerLocked || e.button !== 0) return;
      this.fireQueued = true;
      this.fireHeld = true;
      e.preventDefault();
    });
    window.addEventListener("mouseup", (e) => {
      if (e.button === 0) this.fireHeld = false;
    });
  }

  // Consome um disparo pendente (dispara no máx. 1×/frame por clique).
  consumeFire(): boolean {
    const f = this.fireQueued;
    this.fireQueued = false;
    return f;
  }

  // Botão de disparo segurado (para armas automáticas na FASE 10).
  get isFireHeld(): boolean {
    return this.fireHeld;
  }

  get isPointerLocked(): boolean {
    return this.pointerLocked;
  }

  isKeyDown(code: string): boolean {
    return this.keys.has(code);
  }

  // Retorna o delta de mouse acumulado e o zera. Deve ser chamado
  // exatamente uma vez por frame (no update da câmera).
  consumeMouseDelta(): { dx: number; dy: number } {
    const delta = { dx: this.mouseDX, dy: this.mouseDY };
    this.mouseDX = 0;
    this.mouseDY = 0;
    return delta;
  }
}

src/core/math/mat4.ts:
// ============================================================
//  mat4.ts — Matrizes 4x4 (CPU)
// ------------------------------------------------------------
//  Matemática de matrizes rodando na CPU. São cálculos pequenos
//  (uma matriz por objeto/câmera por frame), então fazê-los na CPU
//  é o correto — o trabalho PESADO e paralelo (multiplicar CADA
//  vértice pela matriz) acontece na GPU, dentro do vertex shader.
//
//  Convenção: COLUNA-MAJOR (column-major), igual ao WGSL/WebGPU.
//  Um Float32Array de 16 posições representa a matriz assim:
//     | m0  m4  m8   m12 |
//     | m1  m5  m9   m13 |
//     | m2  m6  m10  m14 |
//     | m3  m7  m11  m15 |
//
//  IMPORTANTE: em WebGPU o espaço de clip tem Z no intervalo [0, 1]
//  (diferente do OpenGL, que usa [-1, 1]). A projeção perspectiva
//  abaixo já mapeia para [0, 1].
// ============================================================

export type Mat4 = Float32Array<ArrayBuffer>;

// Matriz identidade.
export function identity(): Mat4 {
  const m = new Float32Array(16);
  m[0] = 1;
  m[5] = 1;
  m[10] = 1;
  m[15] = 1;
  return m;
}

// Multiplicação de matrizes: out = a * b (column-major).
export function multiply(a: Mat4, b: Mat4): Mat4 {
  const out = new Float32Array(16);
  for (let col = 0; col < 4; col++) {
    for (let row = 0; row < 4; row++) {
      let sum = 0;
      for (let k = 0; k < 4; k++) {
        sum += a[k * 4 + row] * b[col * 4 + k];
      }
      out[col * 4 + row] = sum;
    }
  }
  return out;
}

// Multiplica uma cadeia de matrizes da esquerda p/ a direita:
// chain(A, B, C) = A * B * C.
export function chain(...mats: Mat4[]): Mat4 {
  let out = identity();
  for (const m of mats) out = multiply(out, m);
  return out;
}

// Translação.
export function translation(x: number, y: number, z: number): Mat4 {
  const m = identity();
  m[12] = x;
  m[13] = y;
  m[14] = z;
  return m;
}

// Escala não-uniforme.
export function scaling(x: number, y: number, z: number): Mat4 {
  const m = new Float32Array(16);
  m[0] = x;
  m[5] = y;
  m[10] = z;
  m[15] = 1;
  return m;
}

// Rotação em torno do eixo X.
export function rotationX(rad: number): Mat4 {
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  const m = identity();
  m[5] = c;
  m[6] = s;
  m[9] = -s;
  m[10] = c;
  return m;
}

// Rotação em torno do eixo Y.
export function rotationY(rad: number): Mat4 {
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  const m = identity();
  m[0] = c;
  m[2] = -s;
  m[8] = s;
  m[10] = c;
  return m;
}

// Projeção perspectiva (right-handed, Z de clip em [0, 1] p/ WebGPU).
//   fovY   — campo de visão vertical em radianos
//   aspect — largura / altura
//   near   — plano de corte próximo (> 0)
//   far    — plano de corte distante
export function perspective(fovY: number, aspect: number, near: number, far: number): Mat4 {
  const f = 1.0 / Math.tan(fovY / 2);
  const m = new Float32Array(16);
  m[0] = f / aspect;
  m[5] = f;
  m[11] = -1;
  const nf = 1 / (near - far);
  m[10] = far * nf;
  m[14] = far * near * nf;
  return m;
}

// Câmera "olhando para": constrói a view matrix (right-handed).
//   eye    — posição da câmera [x, y, z]
//   target — ponto para onde ela olha
//   up     — vetor "para cima" (geralmente [0, 1, 0])
export function lookAt(
  eye: [number, number, number],
  target: [number, number, number],
  up: [number, number, number],
): Mat4 {
  // z = normalize(eye - target)  (aponta para trás da câmera)
  let zx = eye[0] - target[0];
  let zy = eye[1] - target[1];
  let zz = eye[2] - target[2];
  let len = Math.hypot(zx, zy, zz) || 1;
  zx /= len;
  zy /= len;
  zz /= len;

  // x = normalize(cross(up, z))
  let xx = up[1] * zz - up[2] * zy;
  let xy = up[2] * zx - up[0] * zz;
  let xz = up[0] * zy - up[1] * zx;
  len = Math.hypot(xx, xy, xz) || 1;
  xx /= len;
  xy /= len;
  xz /= len;

  // y = cross(z, x)
  const yx = zy * xz - zz * xy;
  const yy = zz * xx - zx * xz;
  const yz = zx * xy - zy * xx;

  const m = new Float32Array(16);
  m[0] = xx;
  m[1] = yx;
  m[2] = zx;
  m[3] = 0;
  m[4] = xy;
  m[5] = yy;
  m[6] = zy;
  m[7] = 0;
  m[8] = xz;
  m[9] = yz;
  m[10] = zz;
  m[11] = 0;
  m[12] = -(xx * eye[0] + xy * eye[1] + xz * eye[2]);
  m[13] = -(yx * eye[0] + yy * eye[1] + yz * eye[2]);
  m[14] = -(zx * eye[0] + zy * eye[1] + zz * eye[2]);
  m[15] = 1;
  return m;
}

src/game/Camera.ts:
// ============================================================
//  Camera — Câmera em primeira pessoa (CPU)
// ------------------------------------------------------------
//  Guarda o estado da câmera FPS e produz a VIEW MATRIX que será
//  combinada com projection/model e enviada à GPU.
//
//  Estado:
//    - position [x, y, z]
//    - yaw   (rotação horizontal, radianos) — olhar p/ os lados
//    - pitch (rotação vertical, radianos)   — olhar p/ cima/baixo
//    - fov, near, far (parâmetros da projeção)
//
//  Convenção de orientação:
//    yaw = 0 e pitch = 0  → olhando para -Z.
//    forward = (cos(pitch)·sin(yaw), sin(pitch), -cos(pitch)·cos(yaw))
//
//  O pitch é limitado para não "virar de cabeça para baixo".
// ============================================================

import { InputManager } from "../core/InputManager";
import { CollisionSystem } from "../collision/CollisionSystem";
import * as mat4 from "../core/math/mat4";
import { Mat4 } from "../core/math/mat4";

// Limite do pitch: ~89° para cima/baixo.
const PITCH_LIMIT = (89 * Math.PI) / 180;
// Sensibilidade do mouse (radianos por pixel).
const MOUSE_SENSITIVITY = 0.0022;
// Velocidade de deslocamento (unidades por segundo).
const MOVE_SPEED = 4.0;
// Raio de colisão do jogador (cápsula/cilindro visto de cima).
const PLAYER_RADIUS = 0.35;

export class Camera {
  position: [number, number, number];
  yaw: number;
  pitch: number;

  fov: number; // em radianos
  near: number;
  far: number;

  constructor(
    position: [number, number, number] = [0, 1.2, 4],
    yaw = 0,
    pitch = 0,
  ) {
    this.position = position;
    this.yaw = yaw;
    this.pitch = pitch;
    this.fov = (70 * Math.PI) / 180;
    this.near = 0.1;
    this.far = 100;
  }

  // Vetor "para frente" completo (inclui o pitch). Usado para o olhar.
  forward(): [number, number, number] {
    const cp = Math.cos(this.pitch);
    return [cp * Math.sin(this.yaw), Math.sin(this.pitch), -cp * Math.cos(this.yaw)];
  }

  // Atualiza a câmera a partir do input (mouse-look + WASD).
  // Se `collision` for fornecido, o deslocamento é resolvido contra
  // o mapa (o jogador não atravessa paredes). Sem gravidade ainda.
  update(dt: number, input: InputManager, collision?: CollisionSystem): void {
    // ---- Mouse-look ----
    const { dx, dy } = input.consumeMouseDelta();
    this.yaw += dx * MOUSE_SENSITIVITY;
    this.pitch -= dy * MOUSE_SENSITIVITY; // mover mouse p/ cima → olhar p/ cima

    // Limita o pitch.
    if (this.pitch > PITCH_LIMIT) this.pitch = PITCH_LIMIT;
    if (this.pitch < -PITCH_LIMIT) this.pitch = -PITCH_LIMIT;

    // ---- Movimento WASD (no plano XZ, ignorando o pitch) ----
    // Direção "frente" projetada no chão.
    const flatFwd: [number, number, number] = [Math.sin(this.yaw), 0, -Math.cos(this.yaw)];
    // Direção "direita" = (cos(yaw), 0, sin(yaw)).
    const right: [number, number, number] = [Math.cos(this.yaw), 0, Math.sin(this.yaw)];

    let mx = 0;
    let mz = 0;
    if (input.isKeyDown("KeyW")) mz += 1;
    if (input.isKeyDown("KeyS")) mz -= 1;
    if (input.isKeyDown("KeyD")) mx += 1;
    if (input.isKeyDown("KeyA")) mx -= 1;

    // Vetor de movimento combinado.
    let vx = flatFwd[0] * mz + right[0] * mx;
    let vz = flatFwd[2] * mz + right[2] * mx;

    // Normaliza para não andar mais rápido na diagonal.
    const len = Math.hypot(vx, vz);
    if (len > 0) {
      vx /= len;
      vz /= len;
      const step = MOVE_SPEED * dt;
      const dx = vx * step;
      const dz = vz * step;

      if (collision) {
        // Movimento com resolução de colisão (não atravessa paredes).
        // Faixa vertical do jogador: pés um pouco acima do chão.
        const feet = this.position[1] - 1.5;
        const head = this.position[1] + 0.2;
        collision.moveAndCollide(this.position, dx, dz, PLAYER_RADIUS, feet, head);
      } else {
        this.position[0] += dx;
        this.position[2] += dz;
      }
    }
  }

  // View matrix a partir da posição e do vetor de olhar.
  viewMatrix(): Mat4 {
    const f = this.forward();
    const target: [number, number, number] = [
      this.position[0] + f[0],
      this.position[1] + f[1],
      this.position[2] + f[2],
    ];
    return mat4.lookAt(this.position, target, [0, 1, 0]);
  }

  // Projection matrix a partir do aspect ratio atual.
  projectionMatrix(aspect: number): Mat4 {
    return mat4.perspective(this.fov, aspect, this.near, this.far);
  }
}

src/game/GameState.ts:
// ============================================================
//  GameState — Máquina de estados do jogo (CPU)
// ------------------------------------------------------------
//  Controla em que "tela"/modo o jogo está. O loop principal usa
//  isso para decidir o que atualizar (ex.: pausar a jogabilidade
//  quando não está em PLAYING).
//
//  Estados previstos (§27). Nesta FASE 9 usamos PLAYING e GAME_OVER;
//  MENU/PAUSED/LEVEL_COMPLETE entram nas fases de telas/fases.
// ============================================================

export enum GameState {
  MENU = "MENU",
  PLAYING = "PLAYING",
  PAUSED = "PAUSED",
  LEVEL_COMPLETE = "LEVEL_COMPLETE",
  GAME_OVER = "GAME_OVER",
}

export class GameStateManager {
  private current: GameState;

  constructor(initial: GameState = GameState.PLAYING) {
    this.current = initial;
  }

  get state(): GameState {
    return this.current;
  }

  is(state: GameState): boolean {
    return this.current === state;
  }

  set(state: GameState): void {
    this.current = state;
  }
}

src/game/Player.ts:
// ============================================================
//  Player — Estado do jogador (CPU)
// ------------------------------------------------------------
//  Guarda os atributos "de RPG" do jogador. A POSIÇÃO e a
//  orientação continuam na Camera (o corpo/olho do jogador); aqui
//  ficam vida e, futuramente, armadura, munição-base etc.
//
//  FASE 9: apenas HP. Armadura/power-ups entram depois (§16).
// ============================================================

export class Player {
  readonly maxHp = 100;
  hp = 100;

  // Armadura: absorve parte do dano. Sobe com pickups (§16, mais tarde).
  readonly maxArmor = 100;
  armor = 0;

  get isAlive(): boolean {
    return this.hp > 0;
  }

  // Aplica dano (limitado a 0). Retorna o HP resultante.
  takeDamage(amount: number): number {
    if (!this.isAlive) return this.hp;
    this.hp = Math.max(0, this.hp - amount);
    return this.hp;
  }

  // Restaura o jogador (usado ao reiniciar a fase).
  reset(): void {
    this.hp = this.maxHp;
    this.armor = 0;
  }
}

src/game/combat/RaycastSystem.ts:
// ============================================================
//  RaycastSystem — Lança raios contra o mundo (CPU)
// ------------------------------------------------------------
//  Usado pelo tiro (hitscan): a partir da câmera, lançamos um ray
//  e descobrimos o PRIMEIRO inimigo atingido — desde que nenhuma
//  parede esteja na frente (oclusão).
//
//  Técnica: interseção ray × AABB pelo método dos "slabs". Para
//  cada eixo calculamos o intervalo [t1, t2] em que o ray está
//  dentro da faixa da caixa; a interseção dos três intervalos dá
//  a entrada (tmin) e a saída (tmax). Se tmin ≤ tmax e tmin ≥ 0,
//  houve acerto a distância tmin.
//
//  É matemática pequena e sequencial (poucas caixas por tiro),
//  então roda na CPU — condiz com "colisões/raycast na CPU".
// ============================================================

import { Box } from "../../levels/types";
import { Enemy } from "../enemies/Enemy";

export interface RayHit {
  enemy: Enemy;
  distance: number;
}

const EPS = 1e-6;

// Interseção ray × AABB. Retorna a distância de entrada (tmin) ou null.
function rayAABB(
  origin: [number, number, number],
  dir: [number, number, number],
  min: [number, number, number],
  max: [number, number, number],
): number | null {
  let tmin = 0;
  let tmax = Infinity;

  for (let axis = 0; axis < 3; axis++) {
    const o = origin[axis];
    const d = dir[axis];
    if (Math.abs(d) < EPS) {
      // Ray paralelo a este par de planos: só passa se já está dentro.
      if (o < min[axis] || o > max[axis]) return null;
    } else {
      const inv = 1 / d;
      let t1 = (min[axis] - o) * inv;
      let t2 = (max[axis] - o) * inv;
      if (t1 > t2) {
        const tmp = t1;
        t1 = t2;
        t2 = tmp;
      }
      if (t1 > tmin) tmin = t1;
      if (t2 < tmax) tmax = t2;
      if (tmin > tmax) return null;
    }
  }
  return tmin;
}

export class RaycastSystem {
  // Encontra o inimigo vivo mais próximo atingido pelo ray, respeitando
  // a oclusão das paredes (`boxes`). Retorna null se nada for atingido.
  static raycast(
    origin: [number, number, number],
    dir: [number, number, number],
    maxDistance: number,
    enemies: readonly Enemy[],
    boxes: readonly Box[],
  ): RayHit | null {
    // 1) Distância até a parede mais próxima (limita o alcance efetivo).
    let wallDist = maxDistance;
    for (const b of boxes) {
      const min: [number, number, number] = [
        b.center[0] - b.size[0] / 2,
        b.center[1] - b.size[1] / 2,
        b.center[2] - b.size[2] / 2,
      ];
      const max: [number, number, number] = [
        b.center[0] + b.size[0] / 2,
        b.center[1] + b.size[1] / 2,
        b.center[2] + b.size[2] / 2,
      ];
      const t = rayAABB(origin, dir, min, max);
      if (t !== null && t < wallDist) wallDist = t;
    }

    // 2) Inimigo vivo mais próximo, mais perto que a parede.
    let best: RayHit | null = null;
    for (const e of enemies) {
      if (!e.isAlive) continue;
      const s = e.archetype.size;
      const min: [number, number, number] = [
        e.position[0] - s[0] / 2,
        e.position[1] - s[1] / 2,
        e.position[2] - s[2] / 2,
      ];
      const max: [number, number, number] = [
        e.position[0] + s[0] / 2,
        e.position[1] + s[1] / 2,
        e.position[2] + s[2] / 2,
      ];
      const t = rayAABB(origin, dir, min, max);
      if (t !== null && t <= wallDist && (best === null || t < best.distance)) {
        best = { enemy: e, distance: t };
      }
    }

    return best;
  }
}

src/game/enemies/Enemy.ts:
// ============================================================
//  Enemy — Entidade de inimigo (CPU)
// ------------------------------------------------------------
//  Estrutura genérica de inimigo (§10 do documento). Nesta FASE 6
//  o inimigo apenas EXISTE e é desenhado (estado IDLE). A IA que
//  o faz detectar/perseguir/atacar chega na FASE 7; receber dano e
//  morrer, na FASE 8/9.
//
//  Cada arquétipo define os atributos base. Por ora só há o "basic";
//  os tipos "rápido" e "pesado" entram na FASE 12.
// ============================================================

import { EnemyType } from "../../levels/types";

// Máquina de estados do inimigo (comportamento na FASE 7).
export enum EnemyState {
  IDLE = "IDLE",
  ALERT = "ALERT",
  CHASE = "CHASE",
  ATTACK = "ATTACK",
  HURT = "HURT",
  DEAD = "DEAD",
}

// Atributos base de um arquétipo.
export interface EnemyArchetype {
  maxHealth: number;
  speed: number; // unidades por segundo
  damage: number; // dano por ataque (aplicado ao jogador na FASE 9)
  attackRange: number; // alcance do ataque corpo a corpo
  detectionRadius: number; // distância para perceber o jogador
  scoreValue: number; // pontos concedidos ao morrer (FASE 18)
  size: [number, number, number]; // dimensões da mesh
  color: [number, number, number]; // cor base
}

// Tabela de arquétipos. Fácil de estender na FASE 12.
export const ENEMY_ARCHETYPES: Record<EnemyType, EnemyArchetype> = {
  basic: {
    maxHealth: 30,
    speed: 2.2,
    damage: 8,
    attackRange: 1.6,
    detectionRadius: 12,
    scoreValue: 100,
    size: [0.7, 1.8, 0.7],
    color: [0.8, 0.16, 0.16],
  },
};

export class Enemy {
  readonly type: EnemyType;
  readonly archetype: EnemyArchetype;

  // position é o CENTRO da mesh; y = altura/2 para "pisar" no chão (y=0).
  position: [number, number, number];
  rotation: number; // yaw, para onde o inimigo "olha"

  health: number;
  readonly maxHealth: number;
  state: EnemyState;

  // Timers da IA (segundos).
  alertTimer = 0; // tempo restante no estado ALERT
  attackCooldown = 0; // tempo até poder atacar de novo
  hurtTimer = 0; // tempo restante do "flinch" ao levar dano

  constructor(type: EnemyType, x: number, z: number) {
    this.type = type;
    const a = ENEMY_ARCHETYPES[type];
    this.archetype = a;

    this.position = [x, a.size[1] / 2, z];
    this.rotation = 0;
    this.health = a.maxHealth;
    this.maxHealth = a.maxHealth;
    this.state = EnemyState.IDLE;
  }

  get isAlive(): boolean {
    return this.state !== EnemyState.DEAD && this.health > 0;
  }

  // Vira o inimigo para encarar um ponto (usado pela IA).
  faceTowards(x: number, z: number): void {
    const dx = x - this.position[0];
    const dz = z - this.position[2];
    // Mesma convenção da câmera: yaw=0 → -Z, forward=(sin,·,-cos).
    this.rotation = Math.atan2(dx, -dz);
  }

  // Aplica dano. Retorna true se ESTE golpe matou o inimigo (para
  // o chamador contabilizar score/efeitos na hora certa).
  takeDamage(amount: number): boolean {
    if (!this.isAlive) return false;
    this.health -= amount;
    if (this.health <= 0) {
      this.health = 0;
      this.state = EnemyState.DEAD;
      return true;
    }
    // Sobreviveu: leva um "flinch" e fica ciente do jogador.
    this.state = EnemyState.HURT;
    this.hurtTimer = 0.18;
    return false;
  }
}

src/game/enemies/EnemyManager.ts:
// ============================================================
//  EnemyManager — Gerencia todos os inimigos do nível (CPU)
// ------------------------------------------------------------
//  Responsável por criar (spawn), atualizar e fornecer os dados
//  de renderização dos inimigos.
//
//  Renderização: cada inimigo vira uma INSTÂNCIA (mesma técnica do
//  mapa). Aqui montamos, por frame, o Float32Array intercalado
//  [model(16) | cor(4)] que o Renderer envia ao storage buffer
//  dinâmico e desenha com um único draw call.
//
//  FASE 6: spawn + render. `update()` ainda não move nada (IA=FASE 7).
// ============================================================

import { Level } from "../../levels/types";
import { Enemy, EnemyState } from "./Enemy";
import { CollisionSystem } from "../../collision/CollisionSystem";
import { Player } from "../Player";
import * as mat4 from "../../core/math/mat4";

const FLOATS_PER_INSTANCE = 20; // model (16) + cor (4)

// --- Parâmetros da IA ---
const ALERT_TIME = 0.4; // pausa de "percebeu você" antes de perseguir
const ATTACK_RATE = 1.0; // intervalo entre ataques (s)
const LOSE_INTEREST = 1.6; // multiplica detectionRadius: acima disso, desiste
const ATTACK_EXIT = 1.25; // multiplica attackRange: histerese p/ sair do ATTACK

export class EnemyManager {
  private enemies: Enemy[] = [];
  // Buffer reutilizado entre frames para evitar realocação (object pooling
  // do lado da CPU). Recriado só se o número de inimigos aumentar.
  private instanceData: Float32Array<ArrayBuffer> = new Float32Array(0);

  // Cria os inimigos a partir dos spawns do nível.
  spawnFromLevel(level: Level): void {
    this.enemies = level.enemySpawns.map((s) => new Enemy(s.type, s.position[0], s.position[1]));
  }

  get all(): readonly Enemy[] {
    return this.enemies;
  }

  get aliveCount(): number {
    let n = 0;
    for (const e of this.enemies) if (e.isAlive) n++;
    return n;
  }

  // Atualização por frame: máquina de estados da IA.
  //   playerPos — posição do jogador (para detecção/perseguição)
  //   collision — para os inimigos não atravessarem paredes
  //   player    — alvo do dano quando um inimigo ataca
  update(
    dt: number,
    playerPos: [number, number, number],
    collision: CollisionSystem,
    player: Player,
  ): void {
    for (const e of this.enemies) {
      if (!e.isAlive) continue;

      const a = e.archetype;
      // Vetor e distância (no plano XZ) até o jogador.
      const dx = playerPos[0] - e.position[0];
      const dz = playerPos[2] - e.position[2];
      const dist = Math.hypot(dx, dz);

      if (e.attackCooldown > 0) e.attackCooldown -= dt;

      switch (e.state) {
        case EnemyState.IDLE:
          // Percebeu o jogador dentro do raio de detecção?
          if (dist < a.detectionRadius) {
            e.state = EnemyState.ALERT;
            e.alertTimer = ALERT_TIME;
          }
          break;

        case EnemyState.ALERT:
          // Encara o jogador por um instante e então parte para cima.
          e.faceTowards(playerPos[0], playerPos[2]);
          e.alertTimer -= dt;
          if (dist > a.detectionRadius * LOSE_INTEREST) {
            e.state = EnemyState.IDLE;
          } else if (e.alertTimer <= 0) {
            e.state = EnemyState.CHASE;
          }
          break;

        case EnemyState.CHASE:
          e.faceTowards(playerPos[0], playerPos[2]);
          if (dist <= a.attackRange) {
            e.state = EnemyState.ATTACK;
            e.attackCooldown = 0; // ataca assim que chega
          } else if (dist > a.detectionRadius * LOSE_INTEREST) {
            e.state = EnemyState.IDLE; // perdeu o jogador
          } else {
            // Move-se em direção ao jogador, resolvendo colisão com o mapa.
            this.moveTowards(e, dx, dz, dist, dt, collision);
          }
          break;

        case EnemyState.ATTACK:
          e.faceTowards(playerPos[0], playerPos[2]);
          if (dist > a.attackRange * ATTACK_EXIT) {
            e.state = EnemyState.CHASE; // jogador se afastou
          } else if (e.attackCooldown <= 0) {
            // Golpe pronto: aplica dano ao jogador e reinicia o cooldown.
            player.takeDamage(a.damage);
            e.attackCooldown = ATTACK_RATE;
          }
          break;

        case EnemyState.HURT:
          // Breve "flinch" ao levar dano; depois retoma a perseguição.
          e.faceTowards(playerPos[0], playerPos[2]);
          e.hurtTimer -= dt;
          if (e.hurtTimer <= 0) e.state = EnemyState.CHASE;
          break;

        default:
          break; // DEAD é filtrado por isAlive
      }
    }
  }

  // Desloca o inimigo em direção ao jogador (com colisão).
  private moveTowards(
    e: Enemy,
    dx: number,
    dz: number,
    dist: number,
    dt: number,
    collision: CollisionSystem,
  ): void {
    if (dist <= 0.0001) return;
    const inv = 1 / dist;
    const step = e.archetype.speed * dt;
    const mx = dx * inv * step;
    const mz = dz * inv * step;

    // Faixa vertical do inimigo (pés um pouco acima do chão).
    const half = e.archetype.size[1] / 2;
    const radius = e.archetype.size[0] / 2;
    const feet = e.position[1] - half + 0.05;
    const head = e.position[1] + half;
    collision.moveAndCollide(e.position, mx, mz, radius, feet, head);
  }

  // Monta os dados de instância dos inimigos VIVOS.
  // Retorna o array e a contagem (para pass.draw(..., count)).
  buildInstances(): { data: Float32Array<ArrayBuffer>; count: number } {
    const alive = this.enemies.filter((e) => e.isAlive);
    const needed = alive.length * FLOATS_PER_INSTANCE;
    if (this.instanceData.length < needed) {
      this.instanceData = new Float32Array(needed);
    }

    const data = this.instanceData;
    for (let i = 0; i < alive.length; i++) {
      const e = alive[i];
      const a = e.archetype;
      // model = translação(centro) * rotaçãoY(olhar) * escala(tamanho)
      const model = mat4.chain(
        mat4.translation(e.position[0], e.position[1], e.position[2]),
        mat4.rotationY(e.rotation),
        mat4.scaling(a.size[0], a.size[1], a.size[2]),
      );
      // Flash branco enquanto está no "flinch" (feedback de dano).
      const hurt = e.state === EnemyState.HURT;
      const base = i * FLOATS_PER_INSTANCE;
      data.set(model, base);
      data[base + 16] = hurt ? 1.0 : a.color[0];
      data[base + 17] = hurt ? 0.9 : a.color[1];
      data[base + 18] = hurt ? 0.9 : a.color[2];
      data[base + 19] = 1.0;
    }

    return { data, count: alive.length };
  }
}

