// ============================================================
//  Pickup — Item de munição no mapa (CPU)
// ------------------------------------------------------------
//  Um item coletável que flutua/gira no cenário. Ao ser pego,
//  entrega munição de um tipo ao jogador e some do mapa.
// ============================================================

import { AmmoType } from "../weapons/Weapon";

// Cor de cada tipo de munição (para identificar o item de longe).
const AMMO_COLOR: Record<AmmoType, [number, number, number]> = {
  pistol: [0.95, 0.85, 0.2], // amarelo
  shotgun: [0.95, 0.45, 0.15], // laranja
  rifle: [0.2, 0.85, 0.95], // ciano
};

export class Pickup {
  active = true;

  // position é o CENTRO do item; baseY é a altura em torno da qual flutua.
  position: [number, number, number];
  readonly baseY = 0.7;
  readonly ammoType: AmmoType;
  readonly amount: number;
  readonly size: [number, number, number] = [0.5, 0.5, 0.5];
  readonly color: [number, number, number];

  constructor(ammoType: AmmoType, x: number, z: number, amount: number) {
    this.ammoType = ammoType;
    this.amount = amount;
    this.color = AMMO_COLOR[ammoType];
    this.position = [x, this.baseY, z];
  }
}

src/game/pickups/PickupManager.ts:
// ============================================================
//  PickupManager — Gerencia os pickups do nível (CPU)
// ------------------------------------------------------------
//  Cria os pickups, detecta a coleta pelo jogador (distância no
//  plano XZ) e fornece as instâncias para renderização. Reaproveita
//  o MESMO buffer dinâmico dos inimigos (mesmo formato de instância),
//  combinado no main.
//
//  Efeito visual: os itens giram e "flutuam" (bob) via a matriz
//  model — animação barata calculada na CPU, aplicada na GPU.
// ============================================================

import { Level } from "../../levels/types";
import { Pickup } from "./Pickup";
import { WeaponManager } from "../weapons/WeaponManager";
import * as mat4 from "../../core/math/mat4";

const FLOATS_PER_INSTANCE = 20; // model (16) + cor (4)
const COLLECT_RADIUS = 1.2; // distância p/ coletar (jogador + item)
const SPIN_SPEED = 1.6; // rad/s
const BOB_AMPLITUDE = 0.12; // altura do "flutuar"

export class PickupManager {
  private pickups: Pickup[] = [];
  private instanceData: Float32Array<ArrayBuffer> = new Float32Array(0);

  spawnFromLevel(level: Level): void {
    this.pickups = level.ammoSpawns.map(
      (s) => new Pickup(s.ammoType, s.position[0], s.position[1], s.amount),
    );
  }

  // Verifica coleta. Ao pegar, adiciona munição (respeitando o teto)
  // e desativa o item. Retorna true se algo foi coletado neste frame.
  update(playerPos: [number, number, number], weapons: WeaponManager): boolean {
    let collected = false;
    for (const p of this.pickups) {
      if (!p.active) continue;
      const dx = playerPos[0] - p.position[0];
      const dz = playerPos[2] - p.position[2];
      if (Math.hypot(dx, dz) <= COLLECT_RADIUS) {
        const added = weapons.addAmmo(p.ammoType, p.amount);
        // Só consome o item se realmente aproveitou alguma munição
        // (evita "desperdiçar" pickup com a reserva já no máximo).
        if (added > 0) {
          p.active = false;
          collected = true;
        }
      }
    }
    return collected;
  }

  // Instâncias dos pickups ativos, com giro e flutuação em função do tempo.
  buildInstances(time: number): { data: Float32Array<ArrayBuffer>; count: number } {
    const active = this.pickups.filter((p) => p.active);
    const needed = active.length * FLOATS_PER_INSTANCE;
    if (this.instanceData.length < needed) this.instanceData = new Float32Array(needed);

    const data = this.instanceData;
    const bob = Math.sin(time * 2.4) * BOB_AMPLITUDE;
    for (let i = 0; i < active.length; i++) {
      const p = active[i];
      const model = mat4.chain(
        mat4.translation(p.position[0], p.baseY + bob, p.position[2]),
        mat4.rotationY(time * SPIN_SPEED),
        mat4.scaling(p.size[0], p.size[1], p.size[2]),
      );
      const base = i * FLOATS_PER_INSTANCE;
      data.set(model, base);
      data[base + 16] = p.color[0];
      data[base + 17] = p.color[1];
      data[base + 18] = p.color[2];
      data[base + 19] = 1.0;
    }
    return { data, count: active.length };
  }
}

src/game/weapons/Weapon.ts:
// ============================================================
//  Weapon — Arma e seus atributos (CPU)
// ------------------------------------------------------------
//  Sistema de armas MODULAR. Cada arma é definida por um config
//  (dados) + um estado de runtime (munição, cooldown, reload).
//  Adicionar uma arma nova = acrescentar uma entrada em WEAPONS.
//
//  Campos pedidos no §13:
//    damage, fireRate, magazineSize, ammoType, reloadTime,
//    pellets, spread  (+ automatic e range que o hitscan usa).
//
//  O DISPARO em si (raycast/dano) fica no main; aqui cuidamos só
//  da "mecânica da arma": cadência, munição e recarga.
// ============================================================

export type AmmoType = "pistol" | "shotgun" | "rifle";

export interface WeaponConfig {
  name: string;
  damage: number; // dano POR projétil (pellet)
  fireRate: number; // disparos por segundo
  magazineSize: number; // capacidade do pente
  ammoType: AmmoType; // munição consumida / reabastecida
  reloadTime: number; // segundos para recarregar
  pellets: number; // projéteis por disparo (shotgun > 1)
  spread: number; // dispersão angular (radianos)
  automatic: boolean; // true = dispara segurando o botão
  range: number; // alcance do hitscan
  maxReserve: number; // teto da munição de reserva (§15: munição limitada)
}

// Tabela de armas. Índice = tecla (1 = pistola, 2 = shotgun, 3 = rifle).
export const WEAPONS: WeaponConfig[] = [
  {
    name: "PISTOLA",
    damage: 18,
    fireRate: 5,
    magazineSize: 12,
    ammoType: "pistol",
    reloadTime: 1.0,
    pellets: 1,
    spread: 0.0,
    automatic: false,
    range: 60,
    maxReserve: 120,
  },
  {
    name: "SHOTGUN",
    damage: 10,
    fireRate: 1.2,
    magazineSize: 6,
    ammoType: "shotgun",
    reloadTime: 1.4,
    pellets: 8,
    spread: 0.09,
    automatic: false,
    range: 30,
    maxReserve: 60,
  },
  {
    name: "RIFLE",
    damage: 12,
    fireRate: 10,
    magazineSize: 30,
    ammoType: "rifle",
    reloadTime: 1.6,
    pellets: 1,
    spread: 0.02,
    automatic: true,
    range: 70,
    maxReserve: 240,
  },
];

export class Weapon {
  readonly config: WeaponConfig;
  magazine: number; // munição no pente
  reserve: number; // munição de reserva (aumenta com pickups na FASE 11)

  private cooldown = 0; // tempo até o próximo disparo
  reloading = false;
  private reloadTimer = 0;

  constructor(config: WeaponConfig, reserve: number) {
    this.config = config;
    this.magazine = config.magazineSize;
    this.reserve = reserve;
  }

  get canFire(): boolean {
    return this.cooldown <= 0 && !this.reloading && this.magazine > 0;
  }

  get isReloading(): boolean {
    return this.reloading;
  }

  // Consome 1 de munição e arma o cooldown. Chamado quando dispara.
  fire(): void {
    this.magazine -= 1;
    this.cooldown = 1 / this.config.fireRate;
  }

  // Inicia a recarga (se fizer sentido).
  beginReload(): void {
    if (this.reloading) return;
    if (this.magazine >= this.config.magazineSize) return;
    if (this.reserve <= 0) return;
    this.reloading = true;
    this.reloadTimer = this.config.reloadTime;
  }

  // Cancela a recarga (ao trocar de arma).
  cancelReload(): void {
    this.reloading = false;
    this.reloadTimer = 0;
  }

  update(dt: number): void {
    if (this.cooldown > 0) this.cooldown -= dt;
    if (this.reloading) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this.finishReload();
    }
  }

  private finishReload(): void {
    const need = this.config.magazineSize - this.magazine;
    const take = Math.min(need, this.reserve);
    this.magazine += take;
    this.reserve -= take;
    this.reloading = false;
  }
}

src/game/weapons/WeaponManager.ts:
// ============================================================
//  WeaponManager — Inventário e arma atual (CPU)
// ------------------------------------------------------------
//  Guarda todas as armas do jogador, qual está equipada, e expõe
//  operações de troca/recarga. Também recebe munição dos pickups
//  (FASE 11) via addAmmo().
// ============================================================

import { AmmoType, Weapon, WEAPONS } from "./Weapon";

// Reserva inicial de munição por arma (índices casam com WEAPONS).
const STARTING_RESERVE = [48, 24, 90];

export class WeaponManager {
  private readonly weapons: Weapon[];
  private index = 0;

  constructor() {
    this.weapons = WEAPONS.map((cfg, i) => new Weapon(cfg, STARTING_RESERVE[i] ?? 0));
  }

  get current(): Weapon {
    return this.weapons[this.index];
  }

  get currentIndex(): number {
    return this.index;
  }

  // Troca de arma (ignora índice inválido ou igual ao atual).
  switchTo(i: number): void {
    if (i < 0 || i >= this.weapons.length || i === this.index) return;
    this.weapons[this.index].cancelReload(); // recarga não sobrevive à troca
    this.index = i;
  }

  reloadCurrent(): void {
    this.current.beginReload();
  }

  update(dt: number): void {
    this.current.update(dt);
  }

  // Adiciona munição de um tipo à arma compatível, respeitando o teto.
  // Retorna quanto foi de fato adicionado (0 se já estava no máximo).
  addAmmo(type: AmmoType, amount: number): number {
    let added = 0;
    for (const w of this.weapons) {
      if (w.config.ammoType !== type) continue;
      const before = w.reserve;
      w.reserve = Math.min(w.config.maxReserve, w.reserve + amount);
      added += w.reserve - before;
    }
    return added;
  }

  // Restaura o inventário (ao reiniciar a fase).
  reset(): void {
    for (let i = 0; i < this.weapons.length; i++) {
      const w = this.weapons[i];
      w.cancelReload();
      w.magazine = w.config.magazineSize;
      w.reserve = STARTING_RESERVE[i] ?? 0;
    }
    this.index = 0;
  }
}

src/geometry/cube.ts:
// ============================================================
//  cube.ts — Geometria de um cubo unitário (dados na CPU)
// ------------------------------------------------------------
//  Cubo unitário centrado na origem (de -0.5 a 0.5 em cada eixo).
//  É a geometria BASE reutilizada por INSTANCING: desenhamos este
//  mesmo cubo N vezes, cada instância com sua matriz model e cor
//  (ver Renderer + storage buffer).
//
//  Cada vértice: posição (x,y,z) + "shade" (1 float).
//  O shade é um brilho fixo POR FACE, embutido nos dados. Ele NÃO
//  é iluminação de verdade (isso é a FASE 15) — serve só para dar
//  contraste entre as faces e o mapa ficar legível em 3D:
//    topo = 1.0 | frente/trás = 0.75 | laterais = 0.6 | base = 0.45
//
//  36 vértices (6 faces × 2 triângulos × 3), não-indexado. O winding
//  é anti-horário visto de fora, casando com cullMode:"back".
// ============================================================

export const CUBE_FLOATS_PER_VERTEX = 4; // x, y, z, shade

const T = 1.0; // topo
const F = 0.75; // frente/trás
const S = 0.6; // laterais
const B = 0.45; // base

// prettier-ignore
export const CUBE_VERTICES = new Float32Array([
  // ---- face traseira (-z) ----
  -0.5, -0.5, -0.5, F,   0.5,  0.5, -0.5, F,   0.5, -0.5, -0.5, F,
  -0.5, -0.5, -0.5, F,  -0.5,  0.5, -0.5, F,   0.5,  0.5, -0.5, F,
  // ---- face frontal (+z) ----
  -0.5, -0.5,  0.5, F,   0.5, -0.5,  0.5, F,   0.5,  0.5,  0.5, F,
  -0.5, -0.5,  0.5, F,   0.5,  0.5,  0.5, F,  -0.5,  0.5,  0.5, F,
  // ---- face esquerda (-x) ----
  -0.5, -0.5, -0.5, S,  -0.5, -0.5,  0.5, S,  -0.5,  0.5,  0.5, S,
  -0.5, -0.5, -0.5, S,  -0.5,  0.5,  0.5, S,  -0.5,  0.5, -0.5, S,
  // ---- face direita (+x) ----
   0.5, -0.5, -0.5, S,   0.5,  0.5, -0.5, S,   0.5,  0.5,  0.5, S,
   0.5, -0.5, -0.5, S,   0.5,  0.5,  0.5, S,   0.5, -0.5,  0.5, S,
  // ---- face inferior (-y) ----
  -0.5, -0.5, -0.5, B,   0.5, -0.5, -0.5, B,   0.5, -0.5,  0.5, B,
  -0.5, -0.5, -0.5, B,   0.5, -0.5,  0.5, B,  -0.5, -0.5,  0.5, B,
  // ---- face superior (+y) ----
  -0.5,  0.5, -0.5, T,  -0.5,  0.5,  0.5, T,   0.5,  0.5,  0.5, T,
  -0.5,  0.5, -0.5, T,   0.5,  0.5,  0.5, T,   0.5,  0.5, -0.5, T,
]);

export const CUBE_VERTEX_COUNT = CUBE_VERTICES.length / CUBE_FLOATS_PER_VERTEX; // 36

src/gpu/GPUContext.ts:
// ============================================================
//  GPUContext — Camada de inicialização do WebGPU (roda na CPU)
// ------------------------------------------------------------
//  Responsabilidade única: obter e guardar os objetos base do
//  WebGPU e configurar o canvas. NÃO desenha nada — apenas prepara
//  o "hardware" para o Renderer usar.
//
//  Objetos WebGPU inicializados aqui:
//    - GPUAdapter        → representa uma GPU física disponível.
//    - GPUDevice         → interface lógica para enviar comandos à GPU.
//    - GPUCanvasContext  → liga o <canvas> à GPU (destino do render).
//    - formato de textura preferido do canvas.
// ============================================================

export class GPUContext {
  readonly adapter: GPUAdapter;
  readonly device: GPUDevice;
  readonly context: GPUCanvasContext;
  readonly canvas: HTMLCanvasElement;
  readonly format: GPUTextureFormat;

  private constructor(
    adapter: GPUAdapter,
    device: GPUDevice,
    context: GPUCanvasContext,
    canvas: HTMLCanvasElement,
    format: GPUTextureFormat,
  ) {
    this.adapter = adapter;
    this.device = device;
    this.context = context;
    this.canvas = canvas;
    this.format = format;
  }

  // Fábrica assíncrona: toda a negociação com a GPU é assíncrona,
  // por isso não pode ficar no construtor.
  static async create(canvas: HTMLCanvasElement): Promise<GPUContext> {
    // 1) O navegador expõe WebGPU em navigator.gpu.
    if (!navigator.gpu) {
      throw new Error(
        "WebGPU não está disponível neste navegador.\n" +
          "Use Chrome/Edge 113+ ou Firefox recente com WebGPU habilitado.",
      );
    }

    // 2) Pede um adaptador (uma GPU física). Preferimos alta performance.
    const adapter = await navigator.gpu.requestAdapter({
      powerPreference: "high-performance",
    });
    if (!adapter) {
      throw new Error("Nenhum GPUAdapter encontrado (navigator.gpu.requestAdapter retornou null).");
    }

    // 3) Pede um device: a interface lógica pela qual enviamos comandos.
    const device = await adapter.requestDevice();

    // Se o device for perdido (ex.: driver reiniciou), avisamos no console.
    device.lost.then((info) => {
      console.error(`GPUDevice perdido: ${info.reason ?? "desconhecido"} — ${info.message}`);
    });

    // 4) Obtém o contexto WebGPU do canvas — destino final do render.
    const context = canvas.getContext("webgpu");
    if (!context) {
      throw new Error("Não foi possível obter o contexto 'webgpu' do canvas.");
    }

    // 5) Formato de textura preferido do sistema (ex.: bgra8unorm).
    //    Usar o formato preferido evita conversões e melhora performance.
    const format = navigator.gpu.getPreferredCanvasFormat();

    // 6) Configura o context: associa device + formato ao canvas.
    context.configure({
      device,
      format,
      alphaMode: "opaque",
    });

    return new GPUContext(adapter, device, context, canvas, format);
  }

  // Ajusta o tamanho do framebuffer ao tamanho real em pixels do canvas,
  // considerando telas HiDPI (devicePixelRatio). Deve ser chamado no início
  // e sempre que a janela for redimensionada.
  resize(): void {
    const dpr = window.devicePixelRatio || 1;
    const width = Math.max(1, Math.floor(this.canvas.clientWidth * dpr));
    const height = Math.max(1, Math.floor(this.canvas.clientHeight * dpr));

    if (this.canvas.width !== width || this.canvas.height !== height) {
      this.canvas.width = width;
      this.canvas.height = height;
    }
  }
}

