// ============================================================
//  level1.ts — Primeiro mapa (dados)
// ------------------------------------------------------------
//  Uma sala retangular fechada por paredes, com alguns pilares e
//  uma parede interna criando um corredor. Tudo descrito como
//  caixas (Box). O renderer transforma isso em instâncias na GPU.
//
//  Convenção de eixos: X = leste/oeste, Z = norte/sul, Y = cima.
//  O chão fica com o topo em y = 0; as paredes têm altura 3.
// ============================================================

import { Level } from "./types";

const WALL_H = 3; // altura das paredes
const WALL_Y = WALL_H / 2; // centro vertical das paredes

// Cores base (o shade por face vem da geometria do cubo).
const FLOOR = [0.18, 0.18, 0.22] as [number, number, number];
const WALL = [0.45, 0.42, 0.5] as [number, number, number];
const PILLAR = [0.5, 0.3, 0.3] as [number, number, number];

export const level1: Level = {
  id: 1,
  name: "Setor 01 — Corredores",
  playerSpawn: { position: [0, 1.6, 9], yaw: 0 }, // no sul, olhando p/ o norte (-z)
  boxes: [
    // ---- Chão (24 x 24), topo em y = 0 ----
    { center: [0, -0.5, 0], size: [24, 1, 24], color: FLOOR },

    // ---- Paredes externas (sala interna de ~24 x 24) ----
    { center: [0, WALL_Y, -12], size: [24, WALL_H, 1], color: WALL }, // norte (-z)
    { center: [0, WALL_Y, 12], size: [24, WALL_H, 1], color: WALL }, // sul (+z)
    { center: [-12, WALL_Y, 0], size: [1, WALL_H, 24], color: WALL }, // oeste (-x)
    { center: [12, WALL_Y, 0], size: [1, WALL_H, 24], color: WALL }, // leste (+x)

    // ---- Parede interna criando um corredor (com abertura) ----
    { center: [-3, WALL_Y, -3], size: [1, WALL_H, 12], color: WALL },
    { center: [3, WALL_Y, 3], size: [1, WALL_H, 12], color: WALL },

    // ---- Pilares / obstáculos ----
    { center: [6, WALL_Y, -6], size: [2, WALL_H, 2], color: PILLAR },
    { center: [-7, WALL_Y, 5], size: [2, WALL_H, 2], color: PILLAR },
    { center: [8, WALL_Y, 7], size: [2, WALL_H, 2], color: PILLAR },
  ],
  // ---- Inimigos (posições no plano do chão) ----
  enemySpawns: [
    { position: [0, -8], type: "basic" },
    { position: [8, 3], type: "basic" },
    { position: [-8, -6], type: "basic" },
  ],
  // ---- Pickups de munição ----
  ammoSpawns: [
    { position: [-9, -9], ammoType: "pistol", amount: 24 },
    { position: [9, -9], ammoType: "shotgun", amount: 8 },
    { position: [0, 6], ammoType: "rifle", amount: 40 },
    { position: [-9, 9], ammoType: "pistol", amount: 24 },
  ],
};

src/levels/types.ts:
// ============================================================
//  types.ts — Estruturas de dados de um nível (CPU)
// ------------------------------------------------------------
//  O mapa é definido por DADOS, não por chamadas de render fixas.
//  Nesta FASE 4 um nível é essencialmente um conjunto de caixas
//  (Box) — chão, paredes e obstáculos. Nas próximas fases este
//  mesmo Level ganha enemySpawns, ammoSpawns, exit, etc.
// ============================================================

// Uma caixa alinhada aos eixos (AABB), descrita por centro + tamanho.
export interface Box {
  center: [number, number, number]; // centro (x, y, z)
  size: [number, number, number]; // dimensões totais (largura, altura, prof.)
  color: [number, number, number]; // cor base RGB (0..1)
}

import type { AmmoType } from "../game/weapons/Weapon";

// Arquétipos de inimigo disponíveis (mais tipos chegam na FASE 12).
export type EnemyType = "basic";

// Ponto de nascimento de um inimigo, no plano do chão (x, z).
export interface EnemySpawn {
  position: [number, number]; // x, z
  type: EnemyType;
}

// Pickup de munição espalhado pelo mapa (§15).
export interface AmmoSpawn {
  position: [number, number]; // x, z
  ammoType: AmmoType;
  amount: number;
}

export interface Level {
  id: number;
  name: string;
  // Onde o jogador nasce e para onde olha (yaw em radianos).
  playerSpawn: { position: [number, number, number]; yaw: number };
  // Geometria estática do mapa (chão, paredes, obstáculos).
  boxes: Box[];
  // Onde os inimigos nascem.
  enemySpawns: EnemySpawn[];
  // Pickups de munição espalhados pelo mapa.
  ammoSpawns: AmmoSpawn[];
}

src/renderer/Renderer.ts:
// ============================================================
//  Renderer — Desenha a cena usando WebGPU
// ------------------------------------------------------------
//  FASE 4: desenha o MAPA como muitas caixas via INSTANCING.
//  A geometria (um cubo unitário) é enviada UMA vez; cada caixa é
//  uma "instância" com sua própria matriz model e cor, lidas de um
//  STORAGE BUFFER pelo vertex shader (indexado por instance_index).
//
//  Assim, todas as caixas do mapa são desenhadas em UM único draw
//  call (pass.draw(36, numInstances)) e a GPU faz a transformação
//  Model→View→Projection de cada uma em paralelo.
//
//  Divisão CPU x GPU:
//    CPU: monta a matriz da câmera (viewProj) e, uma vez, o array
//         de instâncias (model+cor) a partir do level data.
//    GPU: transforma vértices por instância, faz depth test,
//         rasteriza e colore.
// ============================================================

import { GPUContext } from "../gpu/GPUContext";
import { Mat4 } from "../core/math/mat4";
import * as mat4 from "../core/math/mat4";
import { CUBE_VERTICES, CUBE_VERTEX_COUNT, CUBE_FLOATS_PER_VERTEX } from "../geometry/cube";
import { Box } from "../levels/types";
import cubeVertSrc from "../shaders/cube.vert.wgsl?raw";
import cubeFragSrc from "../shaders/cube.frag.wgsl?raw";

const VERTEX_STRIDE_BYTES = CUBE_FLOATS_PER_VERTEX * Float32Array.BYTES_PER_ELEMENT; // 16 bytes
const DEPTH_FORMAT: GPUTextureFormat = "depth24plus";
const VIEW_UNIFORM_SIZE = 16 * 4; // mat4x4<f32> = 64 bytes
const FLOATS_PER_INSTANCE = 20; // mat4 (16) + cor vec4 (4)
const INSTANCE_STRIDE_BYTES = FLOATS_PER_INSTANCE * 4; // 80 bytes

export class Renderer {
  private readonly gpu: GPUContext;
  private readonly pipeline: GPURenderPipeline;
  private readonly vertexBuffer: GPUBuffer;
  private readonly viewUniformBuffer: GPUBuffer;

  private instanceBuffer: GPUBuffer | null = null;
  private bindGroup: GPUBindGroup | null = null;
  private instanceCount = 0;

  // Conjunto de instâncias DINÂMICO (inimigos e, depois, pickups etc.),
  // reenviado à GPU a cada frame. O buffer cresce sob demanda.
  private entityBuffer: GPUBuffer | null = null;
  private entityBindGroup: GPUBindGroup | null = null;
  private entityCapacityBytes = 0;

  private depthTexture: GPUTexture | null = null;
  private depthView: GPUTextureView | null = null;
  private depthWidth = 0;
  private depthHeight = 0;

  constructor(gpu: GPUContext) {
    this.gpu = gpu;
    const { device, format } = gpu;

    // ---- Geometria base (cubo unitário), enviada uma única vez ----
    this.vertexBuffer = device.createBuffer({
      label: "cube-vertices",
      size: CUBE_VERTICES.byteLength,
      usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(this.vertexBuffer, 0, CUBE_VERTICES);

    // ---- Uniform da câmera (viewProj), atualizado por frame ----
    this.viewUniformBuffer = device.createBuffer({
      label: "view-uniform(viewProj)",
      size: VIEW_UNIFORM_SIZE,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });

    // ---- Shaders ----
    const vertexModule = device.createShaderModule({ label: "cube.vert", code: cubeVertSrc });
    const fragmentModule = device.createShaderModule({ label: "cube.frag", code: cubeFragSrc });

    // ---- Layout do vertex buffer (posição + shade) ----
    const vertexBufferLayout: GPUVertexBufferLayout = {
      arrayStride: VERTEX_STRIDE_BYTES,
      attributes: [
        { shaderLocation: 0, offset: 0, format: "float32x3" }, // position
        { shaderLocation: 1, offset: 3 * 4, format: "float32" }, // shade
      ],
    };

    // ---- Pipeline ----
    this.pipeline = device.createRenderPipeline({
      label: "map-pipeline",
      layout: "auto",
      vertex: {
        module: vertexModule,
        entryPoint: "main",
        buffers: [vertexBufferLayout],
      },
      fragment: {
        module: fragmentModule,
        entryPoint: "main",
        targets: [{ format }],
      },
      primitive: {
        topology: "triangle-list",
        cullMode: "back",
        frontFace: "ccw",
      },
      depthStencil: {
        format: DEPTH_FORMAT,
        depthWriteEnabled: true,
        depthCompare: "less",
      },
    });
  }

  // Recebe as caixas do mapa (level data) e monta o storage buffer
  // de instâncias na GPU. Chamado uma vez ao carregar um nível.
  setBoxes(boxes: Box[]): void {
    const { device } = this.gpu;
    this.instanceCount = boxes.length;

    // Monta, na CPU, o array intercalado: [model(16) | cor(4)] por caixa.
    const data = new Float32Array(boxes.length * FLOATS_PER_INSTANCE);
    for (let i = 0; i < boxes.length; i++) {
      const b = boxes[i];
      // model = translação(centro) * escala(tamanho)
      const model = mat4.multiply(
        mat4.translation(b.center[0], b.center[1], b.center[2]),
        mat4.scaling(b.size[0], b.size[1], b.size[2]),
      );
      const base = i * FLOATS_PER_INSTANCE;
      data.set(model, base); // 16 floats
      data[base + 16] = b.color[0];
      data[base + 17] = b.color[1];
      data[base + 18] = b.color[2];
      data[base + 19] = 1.0; // alpha/padding
    }

    // Recria o buffer com o tamanho exato do nível atual.
    this.instanceBuffer?.destroy();
    this.instanceBuffer = device.createBuffer({
      label: "map-instances",
      size: data.byteLength,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(this.instanceBuffer, 0, data);

    // Bind group liga o uniform da câmera (0) e as instâncias (1).
    this.bindGroup = device.createBindGroup({
      label: "map-bind-group",
      layout: this.pipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: this.viewUniformBuffer } },
        { binding: 1, resource: { buffer: this.instanceBuffer } },
      ],
    });

    void INSTANCE_STRIDE_BYTES; // documenta o stride esperado no shader
  }

  // Garante que o buffer dinâmico de entidades comporta `bytes` e
  // recria o bind group quando necessário. Compartilha o mesmo uniform
  // de câmera (viewProj) que o mapa.
  private ensureEntityCapacity(bytes: number): void {
    if (this.entityBuffer && bytes <= this.entityCapacityBytes) return;
    const { device } = this.gpu;
    this.entityBuffer?.destroy();
    const size = Math.max(bytes, INSTANCE_STRIDE_BYTES); // ao menos 1 instância
    this.entityBuffer = device.createBuffer({
      label: "entity-instances",
      size,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    this.entityBindGroup = device.createBindGroup({
      label: "entity-bind-group",
      layout: this.pipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: this.viewUniformBuffer } },
        { binding: 1, resource: { buffer: this.entityBuffer } },
      ],
    });
    this.entityCapacityBytes = size;
  }

  private ensureDepthTexture(): GPUTextureView {
    const { device, canvas } = this.gpu;
    const w = canvas.width;
    const h = canvas.height;
    if (!this.depthTexture || this.depthWidth !== w || this.depthHeight !== h) {
      this.depthTexture?.destroy();
      this.depthTexture = device.createTexture({
        label: "depth-texture",
        size: [w, h],
        format: DEPTH_FORMAT,
        usage: GPUTextureUsage.RENDER_ATTACHMENT,
      });
      this.depthView = this.depthTexture.createView();
      this.depthWidth = w;
      this.depthHeight = h;
    }
    return this.depthView!;
  }

  // Desenha um frame. Recebe a matriz viewProj (Projection * View) e,
  // opcionalmente, as instâncias dinâmicas (inimigos): `entityData`
  // contém `entityCount` instâncias de 20 floats cada.
  render(viewProj: Mat4, entityData?: Float32Array<ArrayBuffer>, entityCount = 0): void {
    const { device, context } = this.gpu;
    if (!this.bindGroup || this.instanceCount === 0) return;

    device.queue.writeBuffer(this.viewUniformBuffer, 0, viewProj);

    // Envia as instâncias dinâmicas (se houver) ANTES de abrir a pass.
    if (entityData && entityCount > 0) {
      const usedFloats = entityCount * (INSTANCE_STRIDE_BYTES / 4);
      this.ensureEntityCapacity(entityCount * INSTANCE_STRIDE_BYTES);
      device.queue.writeBuffer(this.entityBuffer!, 0, entityData, 0, usedFloats);
    }

    const depthView = this.ensureDepthTexture();
    const encoder = device.createCommandEncoder({ label: "frame-encoder" });
    const colorView = context.getCurrentTexture().createView();

    const pass = encoder.beginRenderPass({
      label: "map-pass",
      colorAttachments: [
        {
          view: colorView,
          clearValue: { r: 0.03, g: 0.03, b: 0.05, a: 1.0 },
          loadOp: "clear",
          storeOp: "store",
        },
      ],
      depthStencilAttachment: {
        view: depthView,
        depthClearValue: 1.0,
        depthLoadOp: "clear",
        depthStoreOp: "store",
      },
    });

    pass.setPipeline(this.pipeline);
    pass.setVertexBuffer(0, this.vertexBuffer);

    // Draw 1: mapa estático (uma instância por caixa).
    pass.setBindGroup(0, this.bindGroup);
    pass.draw(CUBE_VERTEX_COUNT, this.instanceCount);

    // Draw 2: inimigos (instâncias dinâmicas), se houver.
    if (this.entityBindGroup && entityData && entityCount > 0) {
      pass.setBindGroup(0, this.entityBindGroup);
      pass.draw(CUBE_VERTEX_COUNT, entityCount);
    }

    pass.end();

    device.queue.submit([encoder.finish()]);
  }
}

src/shaders/cube.frag.wgsl:
// ============================================================
//  FRAGMENT SHADER — cube.frag.wgsl
// ------------------------------------------------------------
//  Executado NA GPU, uma vez por fragmento (pixel do cubo).
//
//  ENTRA: cor RGB interpolada entre os vértices da face.
//  SAI:   cor final RGBA no framebuffer.
//
//  Ainda sem iluminação (FASE 15). As cores por vértice servem
//  apenas para enxergar a forma 3D e a profundidade.
// ============================================================

struct FragmentInput {
  @location(0) color : vec3<f32>,
};

@fragment
fn main(in : FragmentInput) -> @location(0) vec4<f32> {
  return vec4<f32>(in.color, 1.0);
}

src/shaders/cube.vert.wgsl:
// ============================================================
//  VERTEX SHADER — cube.vert.wgsl (com INSTANCING)
// ------------------------------------------------------------
//  Executado NA GPU, uma vez por vértice DE CADA instância.
//
//  ENTRA:
//    - uniform viewProj: matriz Projection * View (câmera), igual
//      para todas as instâncias (group 0, binding 0).
//    - storage instances[]: um array com a matriz `model` e a cor
//      de CADA caixa do mapa (group 0, binding 1). Indexado pelo
//      @builtin(instance_index).
//    - position (vec3) e shade (f32) do vértice do cubo unitário.
//
//  A GPU calcula, em paralelo para cada vértice/instância:
//      clip = viewProj * model * position
//  ou seja, a transformação Model → View → Projection completa
//  acontece aqui, na GPU.
//
//  SAI: posição em clip space + cor (base * shade da face).
// ============================================================

struct ViewUniforms {
  viewProj : mat4x4<f32>,
};
@group(0) @binding(0) var<uniform> view : ViewUniforms;

// Dados por instância. O layout (mat4 + vec4 = 80 bytes) casa com
// o Float32Array montado pela CPU no Renderer.
struct Instance {
  model : mat4x4<f32>,
  color : vec4<f32>,
};
@group(0) @binding(1) var<storage, read> instances : array<Instance>;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) shade    : f32,
};

struct VertexOutput {
  @builtin(position) clip_position : vec4<f32>,
  @location(0)       color         : vec3<f32>,
};

@vertex
fn main(in : VertexInput, @builtin(instance_index) index : u32) -> VertexOutput {
  var out : VertexOutput;

  let inst = instances[index];

  // Model → View → Projection, tudo na GPU.
  let world = inst.model * vec4<f32>(in.position, 1.0);
  out.clip_position = view.viewProj * world;

  // Cor base da caixa modulada pelo brilho fixo da face.
  out.color = inst.color.rgb * in.shade;

  return out;
}
